export function modelSTL(group){const exploded=group.userData.mechanicalAssembly?.explosionFactor??0;if(exploded)setAssemblyExploded(group,0);try{return assembledSTL(group);}finally{if(exploded)setAssemblyExploded(group,exploded);}}
